import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Button,
  Box,
  Chip,
  IconButton,
} from "@mui/material";

import ArrowBackIcon from "@mui/icons-material/ArrowBack";

import { useEffect, useState } from "react";

import {
  Link,
  useNavigate,
} from "react-router-dom";

import API from "../services/api";

export default function MyBlogs() {

  const [blogs, setBlogs] = useState([]);

  const navigate = useNavigate();

  const user = JSON.parse(
    localStorage.getItem("user")
  );

  useEffect(() => {

    const fetchBlogs = async () => {

      try {

        const response = await API.get(
          `/blogs?author=${user._id}`
        );

        setBlogs(response.data);

      } catch (error) {

        console.log(error);
      }
    };

    fetchBlogs();

  }, [user._id]);

  return (

    <Container
      maxWidth="xl"
      sx={{
        py: 6,
        minHeight: "100vh",
      }}
    >

      {/* BACK BUTTON */}

      <Box
        sx={{
          position: "fixed",
          top: 100,
          left: 30,
          zIndex: 1000,
        }}
      >

        <IconButton
          onClick={() => navigate("/")}
          sx={{
            background: "white",
            boxShadow: 3,
            width: 52,
            height: 52,

            "&:hover": {
              background: "#f5f5f5",
              transform: "scale(1.08)",
            },

            transition: "0.3s",
          }}
        >
          <ArrowBackIcon />
        </IconButton>

      </Box>

      {/* PAGE HEADER */}

      <Box sx={{ mb: 6 }}>

        <Typography
          variant="h3"
          fontWeight={800}
          gutterBottom
        >
          My Blogs
        </Typography>

        <Typography
          variant="h6"
          color="text.secondary"
        >
          Manage all your published blogs here
        </Typography>

      </Box>

      {/* EMPTY STATE */}

      {blogs.length === 0 && (

        <Box
          sx={{
            textAlign: "center",
            mt: 10,
          }}
        >

          <Typography
            variant="h5"
            fontWeight={700}
            gutterBottom
          >
            No blogs yet
          </Typography>

          <Typography
            color="text.secondary"
          >
            Start creating amazing blogs 🚀
          </Typography>

        </Box>
      )}

      {/* BLOG GRID */}

      <Grid container spacing={4}>

        {blogs.map((blog) => (

          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog._id}
          >

            <Card
              sx={{
                height: "100%",
                borderRadius: 5,
                overflow: "hidden",
                boxShadow: 3,
                transition: "0.3s",

                "&:hover": {
                  transform: "translateY(-8px)",
                  boxShadow: 8,
                },
              }}
            >

              <CardMedia
                component="img"
                height="220"
                image={
                  blog.image ||
                  "https://images.unsplash.com/photo-1499750310107-5fef28a66643"
                }
                alt={blog.title}
              />

              <CardContent
                sx={{
                  p: 3,
                }}
              >

                <Chip
                  label={
                    blog.category || "General"
                  }
                  color="primary"
                  sx={{ mb: 2 }}
                />

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{ mb: 1 }}
                >
                  By {user.name}
                </Typography>

                <Typography
                  variant="h5"
                  fontWeight={700}
                  gutterBottom
                >
                  {blog.title}
                </Typography>

                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{
                    mb: 3,
                    minHeight: 60,
                  }}
                >
                  {blog.content?.slice(0, 80)}...
                </Typography>

                <Button
                  component={Link}
                  to={`/blog/${blog._id}`}
                  variant="contained"
                  fullWidth
                  sx={{
                    py: 1.3,
                    borderRadius: 3,
                    fontWeight: 700,
                    textTransform: "none",
                    fontSize: "1rem",
                  }}
                >
                  Read More
                </Button>

              </CardContent>

            </Card>

          </Grid>
        ))}

      </Grid>

    </Container>
  );
}
